from fractions import Fraction
import math

def harmonic_gap(n):
    """H_{2n} - H_n as an exact Fraction."""
    return sum(Fraction(1, k) for k in range(n + 1, 2 * n + 1))

def cauchy_n(eps):
    """Smallest n with 1/n <= eps (the bound for sum 1/k^2)."""
    return math.ceil(1 / Fraction(eps))
